    {
      "source": "aztec/statement_of_basis.pdf",
      "locator": "page 11, section: statement_of_basis",
      "exact_span": "Furthermore, the reported TDS is less than 1 ton/day, monitoring shall continue to be performed once every three months, using grab sample.",
